pub struct StubRunPayload {
    pub step_id: String,
    pub passed: bool,
    pub elapsed_ms: u32,
}

/// Batch 3B (Phase 4G) — one row per [`crate::autonomous_gate::AutonomousGate::decide`]
/// call. `decision` is the [`crate::autonomous_gate::AutonomyDecision`]
