#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct VectorCacheHitRatePayload {
    pub session_id: String,
    pub hits: u32,
    pub misses: u32,
    pub hit_rate_pct: f64,
}

/// C-1 — payload for [`SsbActionType::QueryTrace`].
